using Xunit;

namespace XunitTest;

// G216 (a) Part 1's U1.6g3 rows (DECISIONS BU-74): a call argument's relation to its call is the call's published fact (Taken), and a
// function name at a join source that needs no S is its Function Item (P2). The programs are BU's and R4's probes, copied as written.
public partial class OriginRelationDiagnosticTest
{
    private const string Idg = "func idg<T>(v: T) -> T => v@move\n";

    private const string Thrice = "func thrice(v: i64) -> i64 => v\n";

    // U1.6g3b (the owner's (i), 2026-10-31; SPEC 10.5.1, 14.9.2): typed parts with no common Type at a call argument wait for the call
    // until it has selected and taken the argument (CallRelation.Taken). A part a nested join's step 3 bound (the join's binding, no call
    // involved) is not taken, so the conflict still waits: the call completes it where one candidate applies (g236, g161, g090m, g038ms;
    // and g038, g038m, g038mf, g038mt, g090, which P2 alone failed), no candidate is best with two (g254 and its twin without the inner
    // join, g254n; 10.4), and at a generic callee the waiting callable `idg` binds T, so idg, which needs S and has none, is the one
    // record (g020, g020n; 10.5.3), the call's where no waiting callable is left (g020g, g040fix, and g040 beside the closure's own
    // record). Their twins without the bound part are valid (g038mg, g038msv, g038ms0, g090mv, g038v1, g038v2, g038mv).
    [Theory]
    [InlineData("U1.6g3b", "g236", Twice + Idg + "func g<T>(x: T) -> i32 => 0\nfunc k(c1: bool, gv2: (i64) -> i64, c3: bool, c4: bool) -> i32\n    return g<(i64) -> i64>(if c4 => (if c3 => (if c1 => idg else => func [] (v: i64) -> i64 => v) else => gv2@move) else => twice)\n", "")]
    [InlineData("U1.6g3b", "g161", Stop + Twice + Idg + "func f(x: (i64) -> i64) -> i32 => 0\nfunc k(gv1: (i64) -> i64, c2: bool, c3: bool, gv4: (i64) -> i64, c5: bool, c6: bool, c7: bool, c8: bool) -> i32\n    return f((if c7 => func [] (v) => v else if c8 => (if c5 => twice else if c6 => gv4@move else => (if c2 => idg else if c3 => stop() else => gv1@move)) else => func [] (v: i64) -> i64 => v))\n", "")]
    [InlineData("U1.6g3b", "g090m", Twice + Idg + "func g<T>(x: (T, i32)) -> i32 => 0\nfunc k(c5: bool, gv4: (i64) -> i64, c7: bool) -> i32\n    return g<(i64) -> i64>((if c7 => twice else => (if c5 => gv4@move else => idg), 3))\n", "")]
    [InlineData("U1.6g3b", "g038ms", IdentityT + Twice + Idg + "func f(x: (i64) -> i64) -> i32 => 0\nfunc k(gv1: (i64) -> i64, c2: bool, c4: bool) -> i32\n    return f(if c4 => (if c2 => idg else => gv1@move) else => twice)\n", "")]
    [InlineData("U1.6g3b", "g038", IdentityT + Twice + Idg + "func k(gv1: (i64) -> i64, c2: bool, c3: bool, c4: bool, c5: bool) -> i32\n    let v: ((i64) -> i64, i32) = identity(if c4 => ((if c2 => idg else if c3 => idg else => gv1@move), 3) else if c5 => (twice, 4) else => (twice, 5))\n    return 0\n", "")]
    [InlineData("U1.6g3b", "g038m", IdentityT + Twice + Idg + "func f(x: ((i64) -> i64, i32)) -> i32 => 0\nfunc k(gv1: (i64) -> i64, c2: bool, c4: bool) -> i32\n    return f(if c4 => ((if c2 => idg else => gv1@move), 3) else => (twice, 5))\n", "")]
    [InlineData("U1.6g3b", "g038mf", IdentityT + Twice + Idg + "func f(x: ((i64) -> i64, i32)) -> i32 => 0\nfunc k(gv1: (i64) -> i64, c2: bool, c4: bool) -> i32\n    return f(if c4 => ((if c2 => func [] (v) => v else => gv1@move), 3) else => (twice, 5))\n", "")]
    [InlineData("U1.6g3b", "g038mt", IdentityT + Twice + Idg + "func f(x: ((i64) -> i64, i32)) -> i32 => 0\nfunc k(gv1: (i64) -> i64, c2: bool, c4: bool) -> i32\n    return f(if c4 => ((if c2 => func [] (v: i64) -> i64 => v else => gv1@move), 3) else => (twice, 5))\n", "")]
    [InlineData("U1.6g3b", "g090", Twice + Idg + "func g<T>(x: (T, i32)) -> i32 => 0\nfunc k(gv1: (i64) -> i64, c2: bool, c3: bool, gv4: (i64) -> i64, c5: bool, c6: bool, c7: bool, c8: bool) -> i32\n    return g<(i64) -> i64>((if c7 => twice else if c8 => (if c5 => gv4@move else if c6 => idg else => (if c2 => func [] (v: i64) -> i64 => v else if c3 => gv1@move else => idg)) else => idg, 3))\n", "")]
    [InlineData("U1.6g3b", "g254", Twice + "func f(x: (i64) -> i64) -> i32 => 0\nfunc f(x: (bool) -> bool) -> i32 => 1\nfunc k(gv1: (i64) -> i64, c2: bool, gv3: (i64) -> i64, c4: bool, c5: bool) -> i32\n    return f(label l1: do\n        if c5 => exit to l1 twice\n        exit to l1 (if c4 => gv3@move else => (if c2 => func [] (v: i64) -> i64 => v else => gv1@move))\n    )\n", "AmbiguousBinding_Kd f(label l1: do")]
    [InlineData("U1.6g3b", "g020", Stop + Twice + Idg + "func g<T>(x: T) -> i32 => 0\nfunc k(gv1: (i64) -> i64, c2: bool, c3: bool, c4: bool, c5: bool) -> i32\n    return g((if c4 => (if c2 => func [] (v) => v else if c3 => stop() else => gv1@move) else if c5 => twice else => idg))\n", "UnboundTypeArgument_Kd idg")]
    [InlineData("U1.6g3b", "g038mg", IdentityT + Twice + Idg + "func f(x: ((i64) -> i64, i32)) -> i32 => 0\nfunc k(gv1: (i64) -> i64, c2: bool, c4: bool) -> i32\n    return f(if c4 => ((if c2 => idg else => gv1@move), 3) else => (gv1@move, 5))\n", "")]
    [InlineData("U1.6g3b", "g038msv", IdentityT + Twice + Idg + "func f(x: (i64) -> i64) -> i32 => 0\nfunc k(gv1: (i64) -> i64, c2: bool, c4: bool) -> i32\n    return f(if c4 => (if c2 => gv1@move else => gv1@move) else => twice)\n", "")]
    [InlineData("U1.6g3b", "g038ms0", IdentityT + Twice + Idg + "func f(x: (i64) -> i64) -> i32 => 0\nfunc k(gv1: (i64) -> i64, c2: bool, c4: bool) -> i32\n    return f(if c4 => gv1@move else => twice)\n", "")]
    [InlineData("U1.6g3b", "g090mv", Twice + Idg + "func g<T>(x: (T, i32)) -> i32 => 0\nfunc k(c5: bool, gv4: (i64) -> i64, c7: bool) -> i32\n    return g<(i64) -> i64>((if c7 => twice else => (if c5 => gv4@move else => gv4@move), 3))\n", "")]
    [InlineData("U1.6g3b", "g038v1", IdentityT + Twice + Idg + "func k(gv1: (i64) -> i64, c2: bool, c3: bool, c4: bool, c5: bool) -> i32\n    let v: ((i64) -> i64, i32) = identity(if c4 => (gv1@move, 3) else if c5 => (twice, 4) else => (twice, 5))\n    return 0\n", "")]
    [InlineData("U1.6g3b", "g038v2", IdentityT + Twice + Idg + "func k(gv1: (i64) -> i64, c2: bool, c3: bool, c4: bool, c5: bool) -> i32\n    let v: ((i64) -> i64, i32) = identity(if c4 => ((if c2 => gv1@move else => gv1@move), 3) else if c5 => (twice, 4) else => (twice, 5))\n    return 0\n", "")]
    [InlineData("U1.6g3b", "g038mv", IdentityT + Twice + Idg + "func f(x: ((i64) -> i64, i32)) -> i32 => 0\nfunc k(gv1: (i64) -> i64, c2: bool, c4: bool) -> i32\n    return f(if c4 => ((if c2 => gv1@move else => gv1@move), 3) else => (twice, 5))\n", "")]
