    [InlineData("U1.6g3b", "g040fix", Twice + "func g<T>(x: T) -> i32 => 0\nfunc k(c1: bool, c2: bool, gv3: (i64) -> i64, c4: bool) -> i32\n    return g((if c4 => (if c2 => twice else => (if c1 => twice else => twice)) else => gv3@move))\n", "UnboundTypeArgument_Kd g((if c4 => (if c2 => twice else => (if c1 => twice else => twice)) else => gv3@move))")]
    public void AConflictWaitsUntilItsCallTakesTheArgument(string unit, string form, string body, string records)
        => AssertRecords($"{form} [{unit}]", body, records, null);

    // P2 (SPEC 10.5.3, 14.9.2 step 2; the owner's reading): a function name at a join source that needs no S is its Function Item, a
    // typed part, so the join is typed at its Type and a waiting part beside it takes that Type (step 3), failing at itself when it does
    // not fit: an anonymous function (fs1, fs2, fs3, fs9, g180, c6, v1f) or `idg`, which needs S (fs6, fs7, v1, v1n), at a named call,
    // overloaded or not, and at a value call `h` (the fs rows at h, g036, g064, g189, g203: errors under (i)).
    [Theory]
    [InlineData("U1.6g3b", "fs1", Twice + Idg + "func f(x: (i64) -> i64) -> i32 => 0\nfunc f(x: (bool) -> bool) -> i32 => 1\nfunc k(c: bool) -> i32\n    return f(if c => func [] (v: i64) -> i64 => v else => twice)\n", "TypeMismatch_Kd func [] (v: i64) -> i64 => v")]
    [InlineData("U1.6g3b", "fs2", Twice + Idg + "func f(x: (i64) -> i64) -> i32 => 0\nfunc f(x: (bool) -> bool) -> i32 => 1\nfunc k(c: bool) -> i32\n    return f(if c => func [] (v) => v else => twice)\n", "TypeMismatch_Kd func [] (v) => v")]
    [InlineData("U1.6g3b", "fs3", Twice + Idg + "func f(x: (i64) -> i64) -> i32 => 0\nfunc k(c: bool) -> i32\n    return f(if c => func [] (v) => v else => twice)\n", "TypeMismatch_Kd func [] (v) => v")]
    [InlineData("U1.6g3b", "fs6", Twice + Idg + "func f(x: (i64) -> i64) -> i32 => 0\nfunc f(x: (bool) -> bool) -> i32 => 1\nfunc k(c: bool) -> i32\n    return f(if c => twice else => idg)\n", "UnboundTypeArgument_Kd idg")]
    [InlineData("U1.6g3b", "fs7", Twice + Idg + "func f(x: (i64) -> i64) -> i32 => 0\nfunc k(c: bool) -> i32\n    return f(if c => twice else => idg)\n", "UnboundTypeArgument_Kd idg")]
    [InlineData("U1.6g3b", "fs9", Twice + Idg + "func f(x: (i64) -> i64) -> i32 => 0\nfunc f(x: (bool) -> bool) -> i32 => 1\nfunc k(c: bool) -> i32\n    return f((if c => func [] (v: i64) -> i64 => v else => twice))\n", "TypeMismatch_Kd func [] (v: i64) -> i64 => v")]
