    [InlineData("U1.6g3b", "v1", Twice + Idg + "func fh(x: (i64) -> i64) -> i32 => 0\nfunc k(c: bool, d: bool) -> i32\n    let h = fh\n    return h(if c => (if d => twice else => twice) else => idg)\n", "UnboundTypeArgument_Kd idg")]
